import asyncioimport discordfrom discord import Colorfrom discord.ext import commandsfrom utils.EmbedGeneratorUtil import EmbedGeneratorfrom utils.custom.errors.FingerBangThePoonTangBotError import UserNotInChannelError, BotAlreadyInChannelErrorfrom utils.custom.views.MoveToVoiceChannelButtonView import MoveToVoiceChannelButtonViewclass JoinCommand(commands.Cog):    def __init__(self, bot: commands.Bot):        self.bot = bot    @commands.guild_only()    @commands.has_role("Bot Admin")    @commands.command(name="j", help="Joins The Bot To The Author's Voice Channel, If There Is One")    async def join_1(self, ctx: discord.ext.commands.Context):        """        Joins the bot to the current initiating author's voice channel if they are in one.        :param ctx: This is the discord Interaction we can access data from.        :return:        """        if ctx.author.voice:            try:                await ctx.author.voice.channel.connect()                return True            except discord.ClientException:                if ctx.author.voice.channel != ctx.voice_client.channel:                    await ctx.send(view=MoveToVoiceChannelButtonView(ctx=ctx, bot=self.bot))                raise BotAlreadyInChannelError(error="I Am Already In A Voice Channel. You Can Move Me To Your Current Channel If You Wish!")        else:            raise UserNotInChannelError(error="The Bot Cannot Join Your Channel Because You Are Not In One!")async def setup(bot: commands.Bot):    await bot.add_cog(JoinCommand(bot))